package cn.cloudcurtain.tv;
import android.app.*;import android.os.*;import android.content.*;import android.webkit.*;import org.json.*;import java.lang.reflect.*;import java.util.concurrent.*;import java.io.*;
/** Check the actual public website's API adapter with this account's authorized website token. */
final class AliOfficialWebLiveCheck {
 static void run(Instrumentation t,Bundle r,String hash)throws Exception{
  AliWebAuthorizeProbe.run(t,r,hash);Vault vault=new Vault(t.getTargetContext());JSONObject token=new JSONObject(vault.get("ali_web_probe_token")),saved=new JSONObject(vault.get("ali_token"));if(!token.optString("user_id").equals(saved.optString("user_id")))throw new IOException("Web probe owner mismatch");
  MovieLibrary.Movie movie=null;for(MovieLibrary.Movie m:new MovieLibrary(t.getTargetContext()).movies())if(m.provider==Provider.ALI&&(hash.isEmpty()||Integer.toHexString(m.playbackKey().hashCode()).equals(hash))){movie=m;break;}if(movie==null)throw new IOException("Movie missing");CloudApi api=new CloudApi(Provider.ALI);api.selectAliSpace(movie.space);Method drive=CloudApi.class.getDeclaredMethod("aliDrive",JSONObject.class);drive.setAccessible(true);String driveId=(String)drive.invoke(api,saved);
  CloudBrowserActivity a=(CloudBrowserActivity)t.startActivitySync(new Intent(t.getTargetContext(),CloudBrowserActivity.class).putExtra("provider","ALI").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Field wf=CloudBrowserActivity.class.getDeclaredField("web"),hf=CloudBrowserActivity.class.getDeclaredField("handler");wf.setAccessible(true);hf.setAccessible(true);WebView web=(WebView)wf.get(a);final boolean[] primed={false};final CountDownLatch ready=new CountDownLatch(1);
  String setup="localStorage.setItem('token',"+JSONObject.quote(token.toString())+");sessionStorage.removeItem('token');true";
  t.runOnMainSync(()->{try{((Handler)hf.get(a)).removeCallbacksAndMessages(null);web.stopLoading();web.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView v,String url){if(!AliWebSession.allowed(url))return;if(!primed[0]){primed[0]=true;v.evaluateJavascript(setup,ignore->v.loadUrl("https://www.alipan.com/drive"));}else if(android.net.Uri.parse(url).getPath().startsWith("/drive"))ready.countDown();}});web.loadUrl("https://www.alipan.com/sign/in");}catch(Exception e){throw new RuntimeException(e);}});
  try{
   if(!ready.await(45,TimeUnit.SECONDS))throw new IOException("Official website did not initialize");Thread.sleep(4500);
   JSONObject request=new JSONObject().put("drive_id",driveId).put("file_id",movie.id);
   String start="(function(){window.__cloudProbeResult=null;try{var chunks=window.webpackChunk_ali_aliyun_drive_web_name_;if(!chunks)return 'waiting';chunks.push([[987654321],{},function(req){window.__cloudProbeResult={pending:true};var api=req(67657);var flags=req(38782).Hi();api.k("+request.toString()+").subscribe({next:function(d){window.__cloudProbeResult={available:!!(d.url||d.cdn_url),url:d.url||d.cdn_url||'',preferOpen:!!flags.preferPDSOpenApi,keys:Object.keys(d).sort().join(',')};},error:function(e){window.__cloudProbeResult={error:String(e.code||e.errorCode||'failed'),preferOpen:!!flags.preferPDSOpenApi};}});}]);return 'started';}catch(e){window.__cloudProbeResult={error:'client_initialization'};return 'failed';}})()";
   eval(t,web,start);JSONObject result=null;long until=SystemClock.elapsedRealtime()+50000;while(SystemClock.elapsedRealtime()<until){String value=eval(t,web,"JSON.stringify(window.__cloudProbeResult)");Object decoded=new JSONTokener(value).nextValue();if(decoded instanceof String){Object item=new JSONTokener((String)decoded).nextValue();if(item instanceof JSONObject&&!((JSONObject)item).optBoolean("pending")){result=(JSONObject)item;break;}}Thread.sleep(750);}
   if(result==null)throw new IOException("Official website API did not finish");r.putBoolean("web_sdk_original_available",result.optBoolean("available"));r.putBoolean("web_sdk_prefers_open_api",result.optBoolean("preferOpen"));r.putString("web_sdk_response_keys",result.optString("keys"));String error=result.optString("error");if(error.matches("[A-Za-z0-9_.-]{0,100}"))r.putString("web_sdk_error",error);
   if(UrlRules.isWeb(result.optString("url"))){MediaSpec media=new MediaSpec(result.getString("url"),"Official original probe");media.provider="ALI";media.headers.put("Referer",Provider.ALI.origin);media.headers.put("User-Agent",Net.UA);try(okhttp3.Response reply=Net.client(media).newCall(new okhttp3.Request.Builder().url(media.url).header("Range","bytes=0-4095").build()).execute()){r.putInt("web_original_http",reply.code());r.putInt("web_original_bytes",reply.peekBody(4096).bytes().length);}}
  }finally{vault.remove("ali_web_probe_token");t.runOnMainSync(a::finish);}
 }
 static String eval(Instrumentation t,WebView web,String script)throws Exception{CountDownLatch done=new CountDownLatch(1);String[] value={"null"};t.runOnMainSync(()->web.evaluateJavascript(script,s->{value[0]=s;done.countDown();}));if(!done.await(8,TimeUnit.SECONDS))throw new IOException("Website script timeout");return value[0];}
}
